INSERT INTO decade_pairs VALUES
('country','country_roads','coal_miners',ARRAY['perspective', 'community', 'texture'],'A road song for the whole bus, or a portrait of where you came from?','John Denver leans toward feeling; Loretta Lynn leans toward witness.',89),
('country','country_roads','mammas_dont',ARRAY['perspective', 'transformation', 'texture'],'West Virginia heaven, or a warning label for the cowboy myth?','John Denver leans toward feeling; Waylon Jennings & Willie Nelson leans toward witness.',89),
('country','mammas_dont','coal_miners',ARRAY['community'],'Two outlaws trading advice, or one woman telling it straight?','Waylon Jennings & Willie Nelson leans toward the singalong; Loretta Lynn leans toward solitude.',83),
('country','devil_went_down','mama_hes_crazy',ARRAY['tension', 'confidence', 'movement'],'Fiddle duel with Satan, or a hushed confession to Mama?','Charlie Daniels Band leans toward pressure; The Judds leans toward release.',89),
('country','highwayman','forever_ever_amen',ARRAY['transformation', 'scale', 'perspective'],'Four souls across four lifetimes, or one promise that never moves?','The Highwaymen leans toward taking you somewhere; Randy Travis leans toward holding its shape.',89),
('country','devil_went_down','islands_stream',ARRAY['tension', 'perspective', 'texture'],'Bet your soul on a bow, or float off on a velvet duet?','Charlie Daniels Band leans toward pressure; Kenny Rogers & Dolly Parton leans toward release.',89),
('country','devil_went_down','forever_ever_amen',ARRAY['tension', 'perspective', 'transformation'],'Hellfire showdown, or a front-porch vow?','Charlie Daniels Band leans toward pressure; Randy Travis leans toward release.',89),
('country','mama_hes_crazy','guitar_town',ARRAY['confidence', 'movement', 'texture'],'Harmonies that tremble, or a guitar that won''t stay home?','The Judds leans toward vulnerability; Steve Earle leans toward command.',89),
('country','devil_went_down','highwayman',ARRAY['movement', 'immersion', 'atmosphere'],'Win it in one breakneck round, or let the legend unfold slowly?','Charlie Daniels Band leans toward forward motion; The Highwaymen leans toward stillness.',89),
('country','islands_stream','highwayman',ARRAY['perspective', 'transformation', 'immersion'],'Two hearts in the shallows, or ghosts riding the long horizon?','Kenny Rogers & Dolly Parton leans toward feeling; The Highwaymen leans toward witness.',89),
('country','guitar_town','highwayman',ARRAY['immersion', 'transformation', 'atmosphere'],'Gas pedal and a Telecaster, or a reincarnation epic?','Steve Earle leans toward immediacy; The Highwaymen leans toward slow reveal.',89),
('country','any_man_of_mine','strawberry_wine',ARRAY['confidence', 'community', 'atmosphere'],'Lay down the rules, or drown in one August memory?','Shania Twain leans toward command; Deana Carter leans toward vulnerability.',89),
('country','strawberry_wine','achy_breaky',ARRAY['community', 'atmosphere', 'movement'],'Summer you can still taste, or the whole bar doing the steps?','Deana Carter leans toward solitude; Billy Ray Cyrus leans toward the singalong.',89),
('country','chattahoochee','strawberry_wine',ARRAY['community', 'atmosphere', 'movement'],'Muddy-river party, or the first heartbreak in slow motion?','Alan Jackson leans toward the singalong; Deana Carter leans toward solitude.',89),
('country','any_man_of_mine','achy_breaky',ARRAY['texture', 'scale', 'confidence'],'Shania''s demands in stadium chrome, or a mullet''s plea in denim?','Shania Twain leans toward refinement; Billy Ray Cyrus leans toward rawness.',89),
('country','chattahoochee','achy_breaky',ARRAY['perspective'],'Riverbank stories, or don''t-tell-my-heart dance-floor sugar?','Alan Jackson leans toward witness; Billy Ray Cyrus leans toward feeling.',83),
('country','whiskey_lullaby','redneck_woman',ARRAY['confidence', 'community', 'atmosphere'],'The saddest ballad on the radio, or a hell-yeah for the trailer park?','Brad Paisley feat. Alison Krauss leans toward vulnerability; Gretchen Wilson leans toward command.',89),
('country','whiskey_lullaby','gunpowder_lead',ARRAY['confidence', 'movement', 'atmosphere'],'Grief that drinks itself quiet, or a shotgun loaded for payback?','Brad Paisley feat. Alison Krauss leans toward vulnerability; Miranda Lambert leans toward command.',89),
('country','goodbye_earl','whiskey_lullaby',ARRAY['confidence', 'movement', 'community'],'A cheerful murder plot, or a funeral sung in harmony?','Dixie Chicks leans toward command; Brad Paisley feat. Alison Krauss leans toward vulnerability.',89),
('country','jesus_take_wheel','redneck_woman',ARRAY['confidence', 'transformation', 'texture'],'Surrender the steering wheel, or kick open the honky-tonk door?','Carrie Underwood leans toward vulnerability; Gretchen Wilson leans toward command.',89),
('country','jesus_take_wheel','gunpowder_lead',ARRAY['confidence', 'texture', 'movement'],'Pray on the ice, or wait on the porch with a gun?','Carrie Underwood leans toward vulnerability; Miranda Lambert leans toward command.',89),
('country','live_like_dying','redneck_woman',ARRAY['transformation', 'texture', 'confidence'],'A diagnosis that changes everything, or a party that changes nothing?','Tim McGraw leans toward taking you somewhere; Gretchen Wilson leans toward holding its shape.',89),
('country','live_like_dying','gunpowder_lead',ARRAY['tension', 'confidence', 'texture'],'Make peace with time, or settle a score tonight?','Tim McGraw leans toward release; Miranda Lambert leans toward pressure.',89),
('country','goodbye_earl','jesus_take_wheel',ARRAY['confidence', 'movement', 'transformation'],'Take matters into your own hands, or hand them over completely?','Dixie Chicks leans toward command; Carrie Underwood leans toward vulnerability.',89),
('country','die_a_happy_man','mama_broken_heart',ARRAY['tension', 'movement', 'confidence'],'Slow dance in the kitchen, or wreck the bar in heels?','Thomas Rhett leans toward release; Miranda Lambert leans toward pressure.',89),
('country','cruise','die_a_happy_man',ARRAY['community', 'movement', 'confidence'],'Windows down with the whole town, or one candlelit night for two?','Florida Georgia Line leans toward the singalong; Thomas Rhett leans toward solitude.',89),
('country','mama_broken_heart','body_like_back_road',ARRAY['tension', 'texture', 'perspective'],'Smash the mascara, or cruise the curves at twenty miles an hour?','Miranda Lambert leans toward pressure; Sam Hunt leans toward release.',89),
('country','cruise','mama_broken_heart',ARRAY['tension', 'texture', 'perspective'],'Tailgate sunshine, or a breakup with broken glass?','Florida Georgia Line leans toward release; Miranda Lambert leans toward pressure.',89),
('country','cruise','body_like_back_road',ARRAY['community', 'scale'],'Truck-bed singalong, or a private drive down a dirt road?','Florida Georgia Line leans toward the singalong; Sam Hunt leans toward solitude.',86),
('country','die_a_happy_man','body_like_back_road',ARRAY['confidence', 'movement'],'Tender devotion, or a slick come-on with a pickup beat?','Thomas Rhett leans toward vulnerability; Sam Hunt leans toward command.',86),
('country','i_had_some_help','burn_burn_burn',ARRAY['texture', 'community', 'confidence'],'Arena-size finger pointing, or one guy and a cracked acoustic?','Post Malone feat. Morgan Wallen leans toward refinement; Zach Bryan leans toward rawness.',89),
('country','a_bar_song','burn_burn_burn',ARRAY['community', 'confidence', 'texture'],'The whole bar on the chorus, or burning alone on a back step?','Shaboozey leans toward the singalong; Zach Bryan leans toward solitude.',89),
('country','white_horse_stapleton','a_bar_song',ARRAY['tension', 'community', 'transformation'],'Riff like a storm warning, or one more round for everybody?','Chris Stapleton leans toward pressure; Shaboozey leans toward release.',89),
('country','white_horse_stapleton','i_had_some_help',ARRAY['texture', 'tension', 'community'],'Southern rock with teeth, or a glossy duet blaming everyone?','Chris Stapleton leans toward rawness; Post Malone feat. Morgan Wallen leans toward refinement.',89),
('country','white_horse_stapleton','burn_burn_burn',ARRAY['scale', 'confidence', 'tension'],'Gale-force refusal, or a confession you could barely hear?','Chris Stapleton leans toward vastness; Zach Bryan leans toward intimacy.',89),
('country','tennessee_orange','white_horse_stapleton',ARRAY['scale', 'confidence', 'texture'],'A secret crush in the wrong colors, or a man riding off for good?','Megan Moroney leans toward intimacy; Chris Stapleton leans toward vastness.',89),
('country','tennessee_orange','a_bar_song',ARRAY['confidence', 'community', 'movement'],'Whisper it to your mama, or shout it across the dance floor?','Megan Moroney leans toward vulnerability; Shaboozey leans toward command.',89),
('country','tennessee_orange','i_had_some_help',ARRAY['confidence', 'scale', 'movement'],'Falling quietly, or blaming loudly?','Megan Moroney leans toward vulnerability; Post Malone feat. Morgan Wallen leans toward command.',89),
('metal','peace_sells','holy_diver',ARRAY['atmosphere', 'transformation', 'scale'],'A sneer at the system, or a gallop through fantasy?','Megadeth leans toward statement; Dio leans toward immersive mood.',89),
