('metal','roots_bloody','sober_tool',ARRAY['confidence', 'texture', 'community'],'Tribal drums in the dirt, or a lonely spiral through the bass?','Sepultura leans toward command; Tool leans toward vulnerability.',89),
('metal','beautiful_people','sober_tool',ARRAY['confidence', 'immersion', 'community'],'Stomp the fashion parade, or sink into the fog?','Marilyn Manson leans toward command; Tool leans toward vulnerability.',89),
('metal','roots_bloody','freak_on_leash',ARRAY['confidence', 'perspective', 'texture'],'Shout your heritage, or scat through your own breakdown?','Sepultura leans toward command; Korn leans toward vulnerability.',89),
